\label{prop: rearranged PBW}
    The quantum supergroup $U_q(\mathfrak{sl}(2|1))$ has basis the products of the form $$K_1^{a_1}K_2^{a_2}E_1^{a}F_1^b F_{12}^{\epsilon_1}F_{2}^{\epsilon_2}E_{12}^{\epsilon_1'}E_{2}^{\epsilon_2'}$$
    where $a_1,a_2\in \mathbb{Z}, a,b\in \mathbb{Z}_{\geq 0}$ and $\epsilon_1,\epsilon_2,\epsilon'_1,\epsilon'_2\in \{0,1\}$.

\label{lemma: PBW on V(n,a)}
The vectors
\begin{equation}
\label{Bna}
F_{12}^{\epsilon_1}F_2^{\epsilon_2}F_1^i v_0, \qquad \epsilon_1,\epsilon_2\in\{0,1\}, \quad 0\leq i \leq n,
\end{equation}
form a basis $\mathcal{B}_{n,\alpha}$ of $V(n,\alpha)$.

\cite{GLN:genus-for-Lie-superalgebras}
\label{lemma: algebraic bound}
    A PBW vector $K_1^{a_1}K_2^{a_2}E_1^{a}F_1^b F_{12}^{\epsilon_1}F_{2}^{\epsilon_2}E_{12}^{\epsilon_1'}E_{2}^{\epsilon_2'}$ acts on $X$ (in the standard basis) by a matrix whose coefficients are polynomials in $q^{-2\alpha}$ (with $\mathbb{Q}(q)$-coefficients) of degree $\leq \epsilon_1'+\epsilon_2'$. In particular, any vector of $U_q(\mathfrak{sl}(2|1))_{\mathbb{Q}}$ acts on $X$ by a matrix whose coefficients lie in $\mathbb{Q}(q)[q^{-2\alpha}]$ and satisfy $\text{max-deg}_{q^{-2\alpha}}\leq 2$.

\cite{GLN:genus-for-Lie-superalgebras}
\label{lemma: coefficients of iotaX}
   The isomorphism $\iota_X:X^*\to X$ has coefficients in $q^{2\alpha}\mathbb{Q}(q)$ in the standard basis of $X^*$ and $X$.

\label{prop: prop surface and coevaluations}
    Let $T_{\Sigma}$ be an $N$-component framed, oriented bottom tangle. Then the Reshetikhin-Turaev operator invariant $\overline{F}(T_{\Sigma},X):\mathbb{C}\to X^{\otimes 2N}$ satisfies
\begin{align}
\label{eq prop: FTX in terms of coev + B}
     \overline{F}(T_{\Sigma},X)=c(q,q^{\alpha})\cdot \overleftarrow{\text{coev}}_{V_{\alpha}}^{\otimes 2N}+B
\end{align}
   \noindent for a coefficient $c(q,q^{\alpha})\in \mathbb{Q}(q)[q^{\pm 2\alpha}]$ and an operator $B:\mathbb{C}\to X^{\otimes 2N}$ with the following properties:
   \begin{enumerate}[(a)]
       \item The coefficients of $B(1)\in X^{\otimes 2N}$ in the standard basis lie in $\mathbb{Q}(q)[q^{\pm 2\alpha}]$ and satisfy $\text{max-deg}_{q^{-2\alpha}}<N$ and  $\text{max-deg}_{q^{2\alpha}}\leq N$. 
       \item The coefficients of the closure $$\text{cl}(B):=(\text{id}_{V_{\alpha}}\otimes \overleftarrow{\text{ev}}_{V_{\alpha}}^{\otimes 2N})\circ (B\otimes \text{id}_{V_{\alpha}}):V_{\alpha}\toV_{\alpha}$$
 (which also lie in $\mathbb{Q}(q)[q^{\pm 2\alpha}]$) satisfy $\text{max-deg}_{q^{\pm 2\alpha}}<N$.
 \item $\text{max-deg}_{q^{\pm 2\alpha}}c(q,q^{\alpha})= N$ (except if $c(q,q^{\alpha})=0$) and the coefficients of $q^{\pm 2\alpha N}$ in $c(q,q^{\alpha})$ coincide with the least/top coefficient of $LG(L;q,q^{2\alpha+1})$. 
   \end{enumerate}

The core is to prove $(a)$. We follow the same steps as in \cite{LNV:Murasugi-sum}.
\medskip

\textbf{Step 1: Apply algebraic bounds to $Z'_T$.} We begin by applying (\ref{eq: RT of T in terms of universal}) to the LHS of (\ref{eq prop: FTX in terms of coev + B}):
\begin{align*}
     \overline{F}(T_{\Sigma},X)=\mathcal{J}_X\circ F(T_{\Sigma},X), \ \ F(T_{\Sigma},X)=P_{X,X^*}\circ L_{(Z'_T)^{ev}}\circ  \overrightarrow{\text{coev}}_X^{\otimes N}
\end{align*}

Applying the algebraic bound of Lemma \ref{lemma: algebraic bound} $N$ times we see that the coefficients of $L_{(Z'_T)^{ev}}\circ  \overrightarrow{\text{coev}}_X^{\otimes N}$, and hence of $F(T_{\Sigma},X)$, are polynomials in $q^{-2\alpha}$ with $\text{max-deg}_{q^{-2\alpha}}\leq 2 N$. Note that since there are exactly $N$ repetitions of $\iota_X$ in $\mathcal{J}_X$, the operator $\mathcal{J}_X$ has coefficients in $q^{2\alpha N}\mathbb{Q}(q)$ by Lemma \ref{lemma: coefficients of iotaX} (this has the effect of ``symmetrizing'' the powers of $q^{-2\alpha}$ in $F(T_{\Sigma},X)$). This proves that the coefficients of $\overline{F}(T_{\Sigma},X)$ are Laurent polynomials in $q^{2\alpha}$ with $\text{max-deg}_{q^{\pm 2\alpha}}\leq  N$\footnote{This immediately implies the genus bound of \cite{KT:Links-Gould} and it is the $\mathfrak{sl}(2|1)$-case of the proof of the genus bound given in \cite{GLN:genus-for-Lie-superalgebras} for all typical representations of type I Lie superalgebras.}. Our purpose then is to pin down the coefficient of $q^{-4\alpha N}$ in $F(T_{\Sigma},X)$. The idea will be to expand $Z'_T$ in the (tensor product) PBW basis of $U_q(\mathfrak{sl}(2|1))_{\mathbb{Q}}^{\otimes N}$ and see which terms contribute (and how) to the power $q^{-4\alpha N}$ in $F(T_{\Sigma},X)$.
\medskip

\def\mathfrak{u}_q{\mathfrak{u}_q}

\textbf{Step 2: Expand $Z'_T$ in PBW and discard low odd-E-powers.} So let's expand $Z'_T$ in the PBW basis. We assume the PBW basis of $U_q(\mathfrak{sl}(2|1))_{\mathbb{Q}}^{\otimes N}$ has been arranged as in Lemma \ref{prop: rearranged PBW}. One can write $$Z'_T=Z^{top} + Z^{low}$$
where $Z^{low}$ is the sum of all terms in the PBW-expansion of $Z'_T$ having some tensor factor of the form $K_1^{a_1}K_2^{a_2}E_1^{a}F_1^b F_{12}^{\epsilon_1}F_{2}^{\epsilon_2}E_{12}^{\epsilon_1'}E_{2}^{\epsilon_2'}$ with $\epsilon'_1+\epsilon'_2<2$ and $Z^{top}$ is an element of the form $$Z^{top}=\bigotimes_{i=1}^N h_i(K,F,E_1)E_{12}E_2$$
where $h_i(K,F,E_1)$ is a polynomial in $K_1^{\pm 1}, K_2^{\pm 1},E_1, F_1, F_{12},F_{2}$ with $\mathbb{Q}(q)$-coefficients for each $i=1,\dots,N$. Note that by Lemma \ref{lemma: algebraic bound}, $Z^{low}$ does not contribute to the terms of highest degree in $q^{-2\alpha}$, more precisely, $F(Z^{low},X)$ has coefficients which are polynomials in $q^{-2\alpha}$  with $\text{max-deg}_{q^{-2\alpha}}< 2N$. Hence
$$\overline{F}(T_{\Sigma},X)=\overline{F}(Z'_T,X)=\overline{F}(Z^{top},X)+\overline{F}(Z^{low},X)$$
where all coefficients of $\overline{F}(Z^{low},X)\in X^{\otimes 2N}$ are Laurent polynomials in $q^{2\alpha}$ with $\text{max-deg}_{q^{-2\alpha}}< N$ and $\text{max-deg}_{q^{2\alpha}}\leq N$.
\medskip

\textbf{Step 3: The top odd-E-power.} It is thus enough to prove
\begin{align}
\label{eq proof prop: FTX in terms of coev + B'}
     \overline{F}(Z^{top},X)=c(q,q^{\alpha})\cdot \overleftarrow{\text{coev}}_{V_{\alpha}}^{\otimes 2N}+B'
\end{align}

\noindent where $B'$ satisfies the same bounds as $B$ given in $(a)$. The crucial point is to note that, since $Z'_T$ has $L_R$-degree zero and $F_2^2=0=F_{12}^2$, $Z^{top}$ must have the form $$Z^{top}=\bigotimes_{i=1}^N f_i(K,E_1,F_1) F_{12}F_2E_{12}E_2$$
where each $f_i=f_i(K,E_1,F_1)$ is a polynomial in $K_1^{\pm 1}, K_2^{\pm 1}, E_1,F_1$.

\medskip

\textbf{Step 4: Applying the cutting lemma.} Now, by Lemma \ref{lemma: ``cointegral'' cutting lemma}, for each $i=1,\dots, N$ we have
\begin{align*} f_i\cdot F_{12}F_2E_{12}E_2|_{X}&=f_i\cdot (\kappa(\alpha)\cdot\overleftarrow{\text{coev}}_{V_{\alpha}}\circ\overrightarrow{\text{ev}}_{V_{\alpha}} + \overline{B})\\
    &=\epsilon(f_i)\cdot \kappa(\alpha)\cdot \overleftarrow{\text{coev}}_{V_{\alpha}}\circ\overrightarrow{\text{ev}}_{V_{\alpha}} + B'_i
\end{align*}
where $B'_i$ is an operator with coefficients that are polynomials in $q^{-2\alpha}$ satisfying $\text{max-deg}_{q^{-2\alpha}}<2$ (note that $f_i=f_i(K,E_1,F_1)$ acts by $\mathbb{Q}(q)$-coefficients by Lemma \ref{lemma: algebraic bound} so $B'_i:=f_i|_X\circ \overline{B}$ has the property if and only if $\overline{B}$ does). We used that $\overleftarrow{\text{coev}}_{V_{\alpha}}$ is a $U_q(\mathfrak{sl}(2|1))$-morphism so that $f_i|_X\circ\overleftarrow{\text{coev}}_{V_{\alpha}}=\epsilon(f_i)\cdot\overleftarrow{\text{coev}}_{V_{\alpha}}$, where $\epsilon$ is the counit of $U_q(\mathfrak{sl}(2|1))$.

\medskip
Thus, writing $Z^{top}= Z^{top}_1\otimes\dots\otimes Z^{top}_N$ it follows that
\begin{figure}[H]
    \centering
    \includegraphics[width=14cm]{proof-cutting-property.pdf}
\end{figure}


\noindent where $B'_0$ is an operator with coefficients polynomials in $q^{-2\alpha}$ with $\text{max-deg}_{q^{-2\alpha}}<2 N$. Thus, letting $$c(q,q^{\alpha})=\prod_{i=1}^N\epsilon(f_i)\cdot \kappa(\alpha)^N$$ and $$B'=P_{X,X}\circ (\iota_X\otimes \text{id}_X)^{\otimes N}\circ B'_0\circ \overrightarrow{\text{coev}}_X^{\otimes N},$$ we get
\begin{figure}[H]
    \centering
    \includegraphics[width=16cm]{proof-developing-FZtop.pdf}
\end{figure}

